       SELECT #{start} time,entrance_id area,service type,sum(sum) count
        FROM ntc_entrance_report

          WHERE report_time >= #{start}
          AND report_time < #{end}

		GROUP BY service , entrance_id
		ORDER BY count desc;

SELECT #{start} time,url type,SUM(sum) count
FROM ntc_reject_url_statistic

  WHERE stat_time >= #{start}
  AND stat_time < #{end}

GROUP BY url
ORDER BY count desc
LIMIT 10;

SELECT #{start} time,url type,ip_addr ip,SUM(sum) count
   FROM ntc_reject_url_statistic

  WHERE stat_time >= #{start}
  AND stat_time < #{end}

   GROUP BY url,ip_addr
   ORDER BY count desc
   LIMIT 10;

SELECT #{start} time ,website type ,sum(sum) count
FROM ntc_reject_website_statistic

  WHERE stat_time >= #{start}
  AND stat_time < #{end}

group by website
ORDER BY count desc
LIMIT 10;

SELECT #{start} time,website type,ip_addr ip,sum count
    FROM ntc_reject_website_statistic

    WHERE stat_time >= #{start}
    AND stat_time < #{end}

    GROUP BY website ,ip_addr
    ORDER BY count desc
    LIMIT 10;

